module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

// Internal signals for the left and right neighbors of each cell.
// Boundaries q[-1] and q[512] are assumed to be 0 (off).

// Left neighbor vector: q << 1
// q[0] becomes 0, q[i] gets q[i-1] for i >= 1.
logic [511:0] left_neigh;
assign left_neigh = q << 1;

// Right neighbor vector: q >> 1
// q[511] becomes 0, q[i] gets q[i+1] for i <= 510.
logic [511:0] right_neigh;
assign right_neigh = q >> 1;

// Next state calculation for Rule 110.
// The truth table from the specification (mapped to Left, Center, Right):
//  111 -> 0
//  110 -> 1 (L C ~R)
//  101 -> 1 (L ~C R)
//  100 -> 0
//  011 -> 1 (~L C R)
//  010 -> 1 (~L C ~R)
//  001 -> 1 (~L ~C R)
//  000 -> 0
logic [511:0] next_q;

always_comb begin
    next_q <= (left_neigh & q & ~right_neigh) |
              (left_neigh & ~q & right_neigh) |
              (~left_neigh & q & right_neigh) |
              (~left_neigh & q & ~right_neigh) |
              (~left_neigh & ~q & right_neigh);
end

// Synchronous update triggered on the positive edge of the clock.
// Active high 'load' inputs the 'data' vector; otherwise the CA advances one step.
always @(posedge clk) begin
    if (load)
        q <= data;
    else
        q <= next_q;
end

endmodule

