module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

    // State machine parameter definitions
    parameter S_IDLE   = 3'b000;
    parameter S_SHIFT1 = 3'b001;
    parameter S_SHIFT2 = 3'b010;
    parameter S_SHIFT3 = 3'b011;
    parameter S_SHIFT4 = 3'b100;
    parameter S_COUNT  = 3'b101;
    parameter S_DONE   = 3'b110;

    // Pattern detection shift register (4 bits)
    reg [3:0] pshift;

    // State flip-flop
    reg [2:0] state;

    // Sequential logic (positive edge-triggered, synchronous reset)
    always @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            pshift <= 4'b0000;
        end else begin
            case (state)
                S_IDLE: begin
                    // Shift in serial data for pattern detection
                    pshift <= {pshift[2:0], data};

                    // If the pattern 1101 is detected, move to shift state
                    if (pshift == 4'b1101)
                        state <= S_SHIFT1;
                    else
                        state <= S_IDLE;
                end

                S_SHIFT1: begin
                    state <= S_SHIFT2;
                end

                S_SHIFT2: begin
                    state <= S_SHIFT3;
                end

                S_SHIFT3: begin
                    state <= S_SHIFT4;
                end

                S_SHIFT4: begin
                    // After 4 cycles of shift_ena, proceed to counting state
                    state <= S_COUNT;
                end

                S_COUNT: begin
                    // Wait until done_counting input is high
                    if (done_counting)
                        state <= S_DONE;
                    else
                        state <= S_COUNT;
                end

                S_DONE: begin
                    // Wait until user acknowledges (ack is high)
                    if (ack)
                        state <= S_IDLE;
                    else
                        state <= S_DONE;
                end

                default: begin
                    state <= S_IDLE;
                end
            endcase
        end
    end

    // Combinational output assignments
    assign shift_ena = (state == S_SHIFT1) || 
                       (state == S_SHIFT2) || 
                       (state == S_SHIFT3) || 
                       (state == S_SHIFT4);

    assign counting = (state == S_COUNT);

    assign done     = (state == S_DONE);

endmodule

