    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

// Pattern History Table: 128 entries of 2-bit saturating counters
reg [1:0] pht [0:127];
// Global History Register: 7-bit
reg [6:0] ghr;

// Index computation for prediction: PC XOR global history
wire [6:0] pred_idx = predict_pc ^ ghr;
// Index computation for training: PC XOR branch history
wire [6:0] train_idx = train_pc ^ train_history;

// Combinational assignment for prediction outputs
// predict_history is the current value of the GHR
assign predict_history = ghr;
// predict_taken is the MSB of the 2-bit counter (1 = taken, 0 = not taken)
assign predict_taken = pht[pred_idx][1];

// Sequential logic: updates on positive clock edge, asynchronous active-high reset
always @(posedge clk or posedge areset) begin
    if (areset) begin
        // Asynchronous reset: zero GHR and initialize PHT to strongly not-taken (2'b00)
        ghr <= 7'b0;
        integer i;
        for (i = 0; i < 128; i = i + 1)
            pht[i] <= 2'b00;
    end else begin
        // Training takes precedence over prediction when both are asserted in the same cycle
        if (train_valid) begin
            // Update PHT 2-bit counter based on actual branch outcome
            if (train_taken)
                pht[train_idx] <= (pht[train_idx] == 2'b11) ? 2'b11 : pht[train_idx] + 1'b1;
            else
                pht[train_idx] <= (pht[train_idx] == 2'b00) ? 2'b00 : pht[train_idx] - 1'b1;
            // Update GHR with the actual taken outcome (recover history to post-branch state;
            // if mispredicted, this recovers GHR to the state immediately after the branch completes)
            ghr <= {ghr[5:0], train_taken};
        end else if (predict_valid) begin
            // Prediction: update GHR with the predicted taken outcome for the predicted branch
            ghr <= {ghr[5:0], pht[pred_idx][1]};
            // PHT is not modified during prediction (training modifies PHT only at the next positive clock edge)
        end
        // If neither valid, sequential state holds (no explicit else needed)
    end
end

endmodule
